package com.groupstoragetracker;

import lombok.Value;

@Value
class GroupStorageTrackedItem
{
	int itemId;
	String name;
	int gePrice;
	boolean stackable;
	int bankQuantity;
	int inventoryQuantity;
	int wornQuantity;
	int groupStorageQuantity;

	int getOutsideQuantity()
	{
		return bankQuantity + inventoryQuantity + wornQuantity;
	}

	boolean isOutsideStorage()
	{
		return getOutsideQuantity() > 0;
	}

	boolean isInGroupStorage()
	{
		return groupStorageQuantity > 0;
	}

	boolean isMissingFromGroupStorage()
	{
		return isOutsideStorage();
	}
}

